-- CSIU District Insights — warehouse schema (SQLite)
-- Layers follow the BSF data map: region/IU -> district -> building -> grade/classroom -> student.
-- Every table carries a `source` column where real and synthetic rows can coexist:
--   'pde'      real public data (Future Ready PA Index / PDE data files)
--   'pays'     real PAYS aggregate survey results (PCCD district profile reports)
--   'sap'      real PDE SAP district summary counts
--   'census'   real Census TIGER boundaries
--   'synthetic' generated by the seeded generator (ALL student / classroom / teacher data)
--   'illustrative' curated but not verified (e.g., program adoptions)

PRAGMA journal_mode = WAL;
PRAGMA foreign_keys = ON;

CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY, value TEXT NOT NULL);

-- ---------------------------------------------------------------- region
CREATE TABLE counties (
  geoid TEXT PRIMARY KEY, name TEXT NOT NULL, lat REAL, lon REAL, source TEXT NOT NULL DEFAULT 'census'
);

CREATE TABLE districts (
  aun INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,          -- short name, e.g. 'Shikellamy'
  pde_name TEXT,                      -- 'Shikellamy SD'
  county_geoid TEXT REFERENCES counties(geoid),
  tiger_geoid TEXT,                   -- joins public/geo/districts.geojson
  lat REAL, lon REAL, sq_miles REAL, website TEXT,
  sis_vendor TEXT NOT NULL DEFAULT 'Sapphire',   -- illustrative
  source TEXT NOT NULL DEFAULT 'pde'
);

-- One row per district per school year of PDE district fast facts.
CREATE TABLE district_years (
  aun INTEGER NOT NULL REFERENCES districts(aun), school_year TEXT NOT NULL,
  enrollment REAL, schools REAL, econ_pct REAL, el_pct REAL, sped_pct REAL, gifted_pct REAL,
  white_pct REAL, black_pct REAL, hispanic_pct REAL, multi_pct REAL, asian_pct REAL,
  foster_pct REAL, homeless_pct REAL, military_pct REAL, ctc_enrollment REAL, charter_enrollment REAL,
  source TEXT NOT NULL DEFAULT 'pde',
  PRIMARY KEY (aun, school_year)
);

-- ---------------------------------------------------------------- buildings
CREATE TABLE buildings (
  id INTEGER PRIMARY KEY,             -- PDE school number (Schl)
  aun INTEGER NOT NULL REFERENCES districts(aun),
  name TEXT NOT NULL,
  level TEXT NOT NULL,                -- 'elementary' | 'intermediate' | 'middle' | 'high' | 'k12'
  grade_low INTEGER NOT NULL, grade_high INTEGER NOT NULL,   -- K = 0
  grades_text TEXT, title1 INTEGER, lat REAL, lon REAL, address TEXT, city TEXT, zip TEXT,
  active INTEGER NOT NULL DEFAULT 1,
  source TEXT NOT NULL DEFAULT 'pde'
);
CREATE INDEX ix_buildings_aun ON buildings(aun);

CREATE TABLE building_years (
  building_id INTEGER NOT NULL REFERENCES buildings(id), school_year TEXT NOT NULL,
  enrollment REAL, econ_pct REAL, el_pct REAL, sped_pct REAL, white_pct REAL, hispanic_pct REAL, black_pct REAL,
  source TEXT NOT NULL DEFAULT 'pde',
  PRIMARY KEY (building_id, school_year)
);

-- Long format real measures from Future Ready PA: proficiency, growth, attendance, graduation...
-- measure keys: ela_prof, math_prof, sci_prof, ela_adv, math_adv, ela_growth, math_growth, sci_growth,
--   regular_attendance, chronic_absent_pct, grade3_reading, grade7_math, grad_4yr, grad_5yr, career_benchmark,
--   rigorous_courses, postsec_transition, el_proficiency
-- subgroup keys: all, econ, swd, el, white, black, hispanic, multi
CREATE TABLE building_measures (
  building_id INTEGER NOT NULL REFERENCES buildings(id), school_year TEXT NOT NULL,
  measure TEXT NOT NULL, subgroup TEXT NOT NULL, value REAL NOT NULL,
  source TEXT NOT NULL DEFAULT 'pde',
  PRIMARY KEY (building_id, school_year, measure, subgroup)
);

-- Enrollment-weighted district roll-ups of building_measures (PDE does not publish district rows).
CREATE TABLE district_measures (
  aun INTEGER NOT NULL REFERENCES districts(aun), school_year TEXT NOT NULL,
  measure TEXT NOT NULL, subgroup TEXT NOT NULL, value REAL NOT NULL, n_buildings INTEGER NOT NULL,
  source TEXT NOT NULL DEFAULT 'pde-derived',
  PRIMARY KEY (aun, school_year, measure, subgroup)
);

CREATE TABLE statewide_measures (
  school_year TEXT NOT NULL, measure TEXT NOT NULL, value REAL NOT NULL, source TEXT NOT NULL DEFAULT 'pde',
  PRIMARY KEY (school_year, measure)
);

-- School improvement designations (TSI / ATSI) for 2026-27.
CREATE TABLE designations (
  building_id INTEGER NOT NULL REFERENCES buildings(id), designation TEXT NOT NULL, subgroup TEXT NOT NULL,
  note TEXT, source TEXT NOT NULL DEFAULT 'pde',
  PRIMARY KEY (building_id, designation, subgroup)
);

-- ---------------------------------------------------------------- district programs & practices
CREATE TABLE programs (
  id TEXT PRIMARY KEY, name TEXT NOT NULL, category TEXT NOT NULL,   -- 'curriculum' | 'intervention' | 'practice' | 'screener' | 'wellness'
  subject TEXT,                       -- 'ela' | 'math' | 'behavior' | 'sel' | 'wellness' | 'attendance' | NULL
  publisher TEXT, description TEXT
);

-- One row per district x program x subject.
CREATE TABLE program_adoptions (
  aun INTEGER NOT NULL REFERENCES districts(aun), program_id TEXT NOT NULL REFERENCES programs(id),
  subject TEXT NOT NULL, adoption_year INTEGER NOT NULL,          -- school year start, e.g. 2021 = 2021-22
  grade_low INTEGER NOT NULL, grade_high INTEGER NOT NULL, tier TEXT,  -- 'tier1' | 'tier2' | 'tier3' | 'all'
  notes TEXT, source TEXT NOT NULL DEFAULT 'illustrative',
  PRIMARY KEY (aun, program_id, subject)
);

-- Screeners & diagnostics in use: which tool each district uses per subject and grade band.
CREATE TABLE screeners_in_use (
  aun INTEGER NOT NULL REFERENCES districts(aun), tool TEXT NOT NULL, subject TEXT NOT NULL,
  grade_low INTEGER NOT NULL, grade_high INTEGER NOT NULL, since_year INTEGER, source TEXT NOT NULL DEFAULT 'illustrative',
  PRIMARY KEY (aun, tool, subject)
);

-- Minutes of instruction per subject per grade band per building (synthetic).
CREATE TABLE instruction_minutes (
  building_id INTEGER NOT NULL REFERENCES buildings(id), subject TEXT NOT NULL, grade_band TEXT NOT NULL,
  minutes_per_day INTEGER NOT NULL, source TEXT NOT NULL DEFAULT 'synthetic',
  PRIMARY KEY (building_id, subject, grade_band)
);

-- Staffing summary per building per year (synthetic).
CREATE TABLE staffing (
  building_id INTEGER NOT NULL REFERENCES buildings(id), school_year TEXT NOT NULL,
  teachers REAL, counselors REAL, social_workers REAL, psychologists REAL, nurses REAL, paraprofessionals REAL,
  student_teacher_ratio REAL, source TEXT NOT NULL DEFAULT 'synthetic',
  PRIMARY KEY (building_id, school_year)
);

-- PAYS results: district (or IU) x year x indicator x grade.
CREATE TABLE pays_results (
  aun INTEGER,                        -- NULL for the IU-wide row
  school_year TEXT NOT NULL, indicator TEXT NOT NULL, grade TEXT NOT NULL,   -- 'all' | '6' | '8' | '10' | '12'
  value REAL NOT NULL, state_value REAL, n_surveyed INTEGER,
  source TEXT NOT NULL,               -- 'pays' | 'synthetic'
  PRIMARY KEY (aun, school_year, indicator, grade)
);

-- SAP district summaries: counts by category (long format).
CREATE TABLE sap_summary (
  aun INTEGER NOT NULL REFERENCES districts(aun), school_year TEXT NOT NULL,
  category TEXT NOT NULL, item TEXT NOT NULL, count INTEGER NOT NULL,
  source TEXT NOT NULL,               -- 'sap' | 'synthetic'
  PRIMARY KEY (aun, school_year, category, item)
);

-- ---------------------------------------------------------------- people (ALL SYNTHETIC)
CREATE TABLE staff (
  id INTEGER PRIMARY KEY, aun INTEGER NOT NULL REFERENCES districts(aun), building_id INTEGER REFERENCES buildings(id),
  first_name TEXT NOT NULL, last_name TEXT NOT NULL, role TEXT NOT NULL,   -- 'teacher' | 'counselor' | 'principal' | 'social_worker' | 'nurse' | 'psychologist'
  email TEXT, source TEXT NOT NULL DEFAULT 'synthetic'
);
CREATE INDEX ix_staff_building ON staff(building_id);

CREATE TABLE classrooms (
  id INTEGER PRIMARY KEY, building_id INTEGER NOT NULL REFERENCES buildings(id), school_year TEXT NOT NULL,
  grade INTEGER NOT NULL, section TEXT NOT NULL, name TEXT NOT NULL,       -- 'Homeroom 6B'
  teacher_id INTEGER NOT NULL REFERENCES staff(id), source TEXT NOT NULL DEFAULT 'synthetic'
);
CREATE INDEX ix_classrooms_building ON classrooms(building_id, school_year);

CREATE TABLE students (
  id INTEGER PRIMARY KEY,             -- synthetic local ID
  state_id TEXT NOT NULL UNIQUE,      -- synthetic PAsecureID-style ID (never a real one)
  aun INTEGER NOT NULL REFERENCES districts(aun), building_id INTEGER NOT NULL REFERENCES buildings(id),
  classroom_id INTEGER REFERENCES classrooms(id),
  first_name TEXT NOT NULL, last_name TEXT NOT NULL, grade INTEGER NOT NULL, gender TEXT NOT NULL,
  race TEXT NOT NULL, econ_disadvantaged INTEGER NOT NULL, iep INTEGER NOT NULL, el INTEGER NOT NULL,
  gifted INTEGER NOT NULL, section504 INTEGER NOT NULL, enrolled_since TEXT NOT NULL, new_to_building INTEGER NOT NULL,
  prior_year_absences INTEGER NOT NULL, prior_year2_absences INTEGER NOT NULL, prior_year3_absences INTEGER NOT NULL,
  -- latent generator traits (kept so analyses can show "similar students"); never shown as-is in the UI
  latent_academic REAL NOT NULL, latent_attendance REAL NOT NULL, latent_behavior REAL NOT NULL, latent_wellness REAL NOT NULL,
  source TEXT NOT NULL DEFAULT 'synthetic'
);
CREATE INDEX ix_students_building ON students(building_id);
CREATE INDEX ix_students_aun ON students(aun);
CREATE INDEX ix_students_classroom ON students(classroom_id);

-- Daily attendance for the current school year (2026-27) to date.
CREATE TABLE attendance_daily (
  student_id INTEGER NOT NULL REFERENCES students(id), date TEXT NOT NULL,
  status TEXT NOT NULL,               -- 'present' | 'absent_excused' | 'absent_unexcused' | 'tardy'
  PRIMARY KEY (student_id, date)
) WITHOUT ROWID;

-- Monthly roll-ups per building (current year + 3 prior years) used for trend charts.
CREATE TABLE building_attendance_monthly (
  building_id INTEGER NOT NULL REFERENCES buildings(id), school_year TEXT NOT NULL, month INTEGER NOT NULL, -- 8..6
  days INTEGER NOT NULL, enrolled INTEGER NOT NULL, absence_rate REAL NOT NULL, chronic_pct_to_date REAL NOT NULL,
  source TEXT NOT NULL DEFAULT 'synthetic',
  PRIMARY KEY (building_id, school_year, month)
);

CREATE TABLE course_grades (
  student_id INTEGER NOT NULL REFERENCES students(id), school_year TEXT NOT NULL, term TEXT NOT NULL,   -- 'MP1' | 'MP2' | 'MP3' | 'MP4' | 'FINAL' | 'CURRENT'
  subject TEXT NOT NULL,              -- 'ELA' | 'Math' | 'Science' | 'Social Studies' | 'Elective'
  letter TEXT NOT NULL, percent REAL NOT NULL,
  PRIMARY KEY (student_id, school_year, term, subject)
) WITHOUT ROWID;

-- Benchmark screener results (3 windows per year) and weekly progress monitoring.
CREATE TABLE screener_results (
  id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id), tool TEXT NOT NULL,
  subject TEXT NOT NULL, school_year TEXT NOT NULL, window TEXT NOT NULL,     -- 'fall' | 'winter' | 'spring'
  measure TEXT NOT NULL, score REAL NOT NULL, percentile REAL, benchmark TEXT NOT NULL,   -- 'above' | 'on_track' | 'approaching' | 'below'
  date TEXT NOT NULL
);
CREATE INDEX ix_screener_student ON screener_results(student_id, subject, school_year);

CREATE TABLE progress_monitoring (
  student_id INTEGER NOT NULL REFERENCES students(id), subject TEXT NOT NULL, date TEXT NOT NULL,
  measure TEXT NOT NULL, score REAL NOT NULL, goal REAL NOT NULL,
  PRIMARY KEY (student_id, subject, date)
) WITHOUT ROWID;

CREATE TABLE behavior_referrals (
  id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id), date TEXT NOT NULL,
  category TEXT NOT NULL,             -- 'disruption' | 'defiance' | 'physical' | 'verbal' | 'tardy' | 'technology' | 'other'
  location TEXT NOT NULL, time_of_day TEXT NOT NULL, action TEXT NOT NULL, minor INTEGER NOT NULL
);
CREATE INDEX ix_referrals_student ON behavior_referrals(student_id, date);

CREATE TABLE nurse_visits (
  student_id INTEGER NOT NULL REFERENCES students(id), date TEXT NOT NULL, reason TEXT NOT NULL,
  PRIMARY KEY (student_id, date, reason)
) WITHOUT ROWID;

-- Project AWARE universal wellness screener (synthetic), fall and spring windows.
CREATE TABLE wellness_screens (
  student_id INTEGER NOT NULL REFERENCES students(id), school_year TEXT NOT NULL, window TEXT NOT NULL,
  anxiety REAL NOT NULL, depression REAL NOT NULL, connectedness REAL NOT NULL, safety REAL NOT NULL,   -- 0..10 scales
  risk_level TEXT NOT NULL,           -- 'low' | 'moderate' | 'high'
  date TEXT NOT NULL,
  PRIMARY KEY (student_id, school_year, window)
) WITHOUT ROWID;

-- Brief weekly teacher check-in ("how are you doing" 1-5) for grades 3-12 (synthetic).
CREATE TABLE wellness_checkins (
  student_id INTEGER NOT NULL REFERENCES students(id), date TEXT NOT NULL, score INTEGER NOT NULL,
  PRIMARY KEY (student_id, date)
) WITHOUT ROWID;

-- Supports delivered: one row per student x intervention episode, with outcomes before/after.
-- This is the "implementation data" table the BSF calls out.
CREATE TABLE interventions (
  id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id), program_id TEXT NOT NULL REFERENCES programs(id),
  domain TEXT NOT NULL,               -- 'academic' | 'attendance' | 'behavior' | 'wellness' | 'sap' | 'family'
  tier TEXT NOT NULL, start_date TEXT NOT NULL, end_date TEXT, status TEXT NOT NULL,   -- 'active' | 'completed' | 'discontinued'
  referral_reason TEXT NOT NULL, days_from_flag_to_start INTEGER,
  sessions_planned INTEGER, sessions_delivered INTEGER, fidelity REAL,       -- 0..1
  funding TEXT,                       -- 'district' | 'Project AWARE' | 'Title I' | 'IDEA' | 'CSIU'
  provider TEXT,                      -- 'school counselor' | 'CSIU behavioral health' | ...
  outcome_measure TEXT NOT NULL,      -- 'absence_rate' | 'referrals_per_month' | 'math_percent' | 'ela_percent' | 'wellness_risk' | 'pm_wcpm'
  pre_value REAL NOT NULL, post_value REAL, improved INTEGER,               -- improved: 1/0, NULL if not yet measured
  notes TEXT
);
CREATE INDEX ix_interventions_student ON interventions(student_id);
CREATE INDEX ix_interventions_program ON interventions(program_id);

-- Outcomes over the same window for EVERY student (prior-year fall half -> spring half), so that students who
-- received a support can be compared with similar students who did not.
CREATE TABLE student_outcomes (
  student_id INTEGER NOT NULL REFERENCES students(id), domain TEXT NOT NULL,   -- 'attendance' | 'behavior' | 'academic' | 'wellness'
  measure TEXT NOT NULL, pre_value REAL NOT NULL, post_value REAL NOT NULL, improved INTEGER NOT NULL,
  PRIMARY KEY (student_id, domain)
) WITHOUT ROWID;

-- Explainable risk index per student (recomputed by scripts/risk.ts; stored for speed).
CREATE TABLE student_risk (
  student_id INTEGER PRIMARY KEY REFERENCES students(id), as_of TEXT NOT NULL,
  score REAL NOT NULL, level TEXT NOT NULL,     -- 'low' | 'watch' | 'moderate' | 'high'
  attendance_pts REAL NOT NULL, behavior_pts REAL NOT NULL, course_pts REAL NOT NULL, screener_pts REAL NOT NULL, wellness_pts REAL NOT NULL,
  factors_json TEXT NOT NULL,         -- [{"factor":"Absences rising quickly","weight":"strong","detail":"..."}]
  strengths_json TEXT NOT NULL,
  flagged_date TEXT
);

-- Contacts, meetings, and notes on a student's support timeline (synthetic).
CREATE TABLE student_contacts (
  id INTEGER PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id), date TEXT NOT NULL,
  kind TEXT NOT NULL,                 -- 'flag' | 'referral' | 'family_call' | 'meeting' | 'note'
  title TEXT NOT NULL, detail TEXT
);
CREATE INDEX ix_contacts_student ON student_contacts(student_id, date);

-- Case management for flagged students.
CREATE TABLE support_plans (
  student_id INTEGER PRIMARY KEY REFERENCES students(id), support_level TEXT NOT NULL,
  case_lead_staff_id INTEGER REFERENCES staff(id), next_meeting TEXT
);

-- Audit of role-scoped access (prototype: demonstrates the logging the student page mentions).
CREATE TABLE access_log (
  id INTEGER PRIMARY KEY, at TEXT NOT NULL, role TEXT NOT NULL, aun INTEGER, building_id INTEGER, staff_id INTEGER,
  action TEXT NOT NULL, target TEXT
);
